get_site_settings.code:
const response = await client.siteSettings.getSiteSettings();
const settings = response.map.site_settings;
console.log(settings.store_details.company_name, settings.domain_settings.website_address);
console.log(settings.brand_kit.palette_name, settings.date_time.admin.time_zone);

patch_site_settings.code:
const response = await client.siteSettings.patchSiteSettings({
    site_settings: {brand_kit: {palette_name: 'Autumn'}, date_time: {hide_time_zone: false}},
});
const settings = response.map.site_settings;
console.log(settings.brand_kit.palette_name, settings.date_time.hide_time_zone);

get_site_settings_section.code:
const response = await client.siteSettings.getSiteSettingsSection('brand_kit');
const brandKit = response.map.brand_kit;
console.log(brandKit.enabled, brandKit.palette_name);
console.log(brandKit.colors.primary, brandKit.colors.secondary, brandKit.colors.accent);
